// Copies the Kotlin/JS ES modules generated by `npm run kmp:build` (src/generated/kmp) next to the
// compiled TypeScript (dist/esm/generated/kmp) so that `import('./generated/kmp/…')` resolves for
// bundlers consuming dist/esm and for rollup when producing dist/plugin(.cjs).js.
import { cpSync, existsSync } from 'node:fs';

const from = 'src/generated';
if (!existsSync(from)) {
  console.error(`[copy-kmp-js] ${from} not found – run "npm run kmp:build" first.`);
  process.exit(1);
}
cpSync(from, 'dist/esm/generated', { recursive: true });
